Action Music.command:
for (let pl of game.playlists.filter(p => p.playing)) {
    await pl.stopAll();
}
const playlist = game.playlists.getName("OST");
const sound = playlist.sounds.getName("Action");
await playlist.updateEmbeddedDocuments("PlaylistSound", [{_id: sound.id, repeat: true, playing: true}]);

