Roll BoM.command:
const table = await fromUuid('Compendium.cha-coc-fvtt-en-starterset.reference-tables.RollTable.WtXT92wxNvHu2YuK')
const draw = await table.draw({ displayChat:false })
await table.toMessage(draw.results, {
  roll: draw.roll,
  messageData: {
    whisper: ChatMessage.getWhisperRecipients('GM').map(doc => doc._id)
  },
  messageOptions: {
    messageMode: '',
    rollMode: ''
  }
})

Activate Dead Man Stomp.command:
const targetSceneID = "GUbRoufM8rzvp3JR";

async function updateSceneNavigationPermissions() {
  for (const scene of game.scenes) {
    if (scene.id === targetSceneID) {
      await scene.update({
        "navigation": true,
        "active": true
      });
      await scene.activate();
    } else {
      await scene.update({
        "navigation": false,
        "ownership": { "default": 0 }
      });
    }
  }
  ui.notifications.info("Scene activated and other scenes hidden from players.");
}

updateSceneNavigationPermissions();

